 AllowDrop=true;DragOver+=(_,e)=>{if(e.Data.GetDataPresent(DataFormats.FileDrop)){e.Effects=DragDropEffects.Copy;e.Handled=true;}};Drop+=(_,e)=>{if(e.Data.GetData(DataFormats.FileDrop) is string[] files){QueueImports(files);e.Handled=true;}};
 }
 void UpdateProfile(){if(profileButton==null)return;var badge=new Grid{Width=150};badge.ColumnDefinitions.Add(new(){Width=new GridLength(44)});badge.ColumnDefinitions.Add(new(){Width=new GridLength(1,GridUnitType.Star)});var avatar=new Border{Width=42,Height=42,CornerRadius=new CornerRadius(21),BorderThickness=new Thickness(2),BorderBrush=Brush("#090909"),Background=new ImageBrush(LoadImage(library.AvatarPath,96)??brandIcon){Stretch=Stretch.UniformToFill}};badge.Children.Add(avatar);var name=new StackPanel{VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(8,0,0,0)};Grid.SetColumn(name,1);badge.Children.Add(name);var title=Text(library.UserName,20,"#F5F5F5",FontWeights.Black);title.TextWrapping=TextWrapping.NoWrap;title.TextTrimming=TextTrimming.CharacterEllipsis;name.Children.Add(title);name.Children.Add(Text("MY PROFILE",9,"#ADADAD",FontWeights.Bold));profileButton.Content=badge;}
